DROP TABLE "/TROTTO/OTTO_SHOPS";

-- rebuild table /TRFIN/COMPANIES: drop-column /TRFIN/COMPANIES./TROTTO/OTTO_ID (column data is lost); drop-column /TRFIN/COMPANIES./TROTTO/ACTIVE (column data is lost); drop-column /TRFIN/COMPANIES./TROTTO/MAIN_SHOP (column data is lost); drop-foreign-key /TRFIN/COMPANIES./TROTTO/MAIN_SHOP (references /TROTTO/OTTO_SHOPS) [DESTRUCTIVE]
CREATE TABLE "/TRFIN/COMPANIES#NEW" (
  "/RT/TENANT" TEXT NOT NULL,
  "COMPANY_ID" TEXT NOT NULL,
  "NAME" TEXT NOT NULL,
  "COUNTRY" TEXT NOT NULL,
  "STATUS" TEXT NOT NULL DEFAULT 'ACTIVE',
  "CAPITAL" INTEGER,
  "FOUNDED_ON" TEXT,
  CONSTRAINT "/TRFIN/COMPANIES#PK" PRIMARY KEY ("/RT/TENANT", "COMPANY_ID"),
  CONSTRAINT "/TRFIN/COMPANIES#FK#/RT/TENANT" FOREIGN KEY ("/RT/TENANT") REFERENCES "/RT/TENANTS" ("TENANT"),
  CONSTRAINT "/TRFIN/COMPANIES#FK#COUNTRY" FOREIGN KEY ("COUNTRY") REFERENCES "/TRFIN/COUNTRIES" ("COUNTRY_CODE"),
  CONSTRAINT "/TRFIN/COMPANIES#CK#/RT/TENANT" CHECK ("/RT/TENANT" IS NULL OR (length("/RT/TENANT") <= 16)),
  CONSTRAINT "/TRFIN/COMPANIES#CK#COMPANY_ID" CHECK ("COMPANY_ID" IS NULL OR (length("COMPANY_ID") <= 10)),
  CONSTRAINT "/TRFIN/COMPANIES#CK#NAME" CHECK ("NAME" IS NULL OR (length("NAME") <= 80)),
  CONSTRAINT "/TRFIN/COMPANIES#CK#COUNTRY" CHECK ("COUNTRY" IS NULL OR (length("COUNTRY") <= 2)),
  CONSTRAINT "/TRFIN/COMPANIES#CK#STATUS" CHECK ("STATUS" IS NULL OR (length("STATUS") <= 10 AND "STATUS" IN ('ACTIVE', 'BLOCKED', 'CLOSED'))),
  CONSTRAINT "/TRFIN/COMPANIES#CK#CAPITAL" CHECK ("CAPITAL" IS NULL OR ("CAPITAL" BETWEEN -999999999999999 AND 999999999999999)),
  CONSTRAINT "/TRFIN/COMPANIES#CK#FOUNDED_ON" CHECK ("FOUNDED_ON" IS NULL OR ("FOUNDED_ON" IS date("FOUNDED_ON")))
) STRICT;
INSERT INTO "/TRFIN/COMPANIES#NEW" ("/RT/TENANT", "COMPANY_ID", "NAME", "COUNTRY", "STATUS", "CAPITAL", "FOUNDED_ON") SELECT "/RT/TENANT", "COMPANY_ID", "NAME", "COUNTRY", "STATUS", "CAPITAL", "FOUNDED_ON" FROM "/TRFIN/COMPANIES";
DROP TABLE "/TRFIN/COMPANIES";
ALTER TABLE "/TRFIN/COMPANIES#NEW" RENAME TO "/TRFIN/COMPANIES";

